// Smooth minimum function for blending shapes
float smoothMin(float a, float b, float k) {
    float h = max(k - abs(a - b), 0.0) / k;
    return min(a, b) - h * h * k * 0.25;
}

// Rotate a point
vec2 rotate(vec2 p, float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return vec2(c * p.x - s * p.y, s * p.x + c * p.y);
}

// Shape functions
float sdEquilateralTriangle(vec2 p, float r) {
    const float k = sqrt(3.0);
    p.x = abs(p.x) - r;
    p.y = p.y + r / k;
    if (p.x + k * p.y > 0.0) p = vec2(p.x - k * p.y, -k * p.x - p.y) / 2.0;
    p.x -= clamp(p.x, -2.0 * r, 0.0);
    return -length(p) * sign(p.y);
}

float sdVesica(vec2 p, float w, float h) {
    float d = 0.5 * (w * w - h * h) / h;
    p = abs(p);
    vec3 c = (w * p.y < d * (p.x - w)) ? vec3(0.0, w, 0.0) : vec3(-d, 0.0, d + h);
    return length(p - c.yx) - c.z;
}

vec2 rotate(vec2 p, vec2 velocity) {
    float angle = atan(velocity.y, velocity.x); // Get rotation angle from velocity
    float c = -cos(angle);
    float s = sin(angle);
    vec2 rotated = vec2(c * p.x - s * p.y, s * p.x + c * p.y); // Rotate p
    rotated.y = -rotated.y; // Flip in the y direction

    return rotated;
}

