float sdFish(vec2 p, vec2 v) {
    //p = rotate(p, rot_angle+ 0.0);
    p = rotate(p, v);
    float factor = 0.05; 
    float body_width = 0.5 * factor;
    float body_length = 1.3 * factor;
    float tail_size = 0.55 * factor;
    float fin_size = 0.75 * factor;

    vec2 tailPos = rotate((p + vec2(-body_length * 1.3, 0.0)), 0.55);
    vec2 finPos = rotate( p + vec2(-body_length * 0.15, -body_width*0.2), 0.45);

    float body = sdVesica(p, body_length, body_width);
    float tail = sdEquilateralTriangle(tailPos, tail_size);
    float fin = sdEquilateralTriangle(finPos, fin_size);

    return smoothMin(fin, (smoothMin(body, tail, 0.3 * factor)), 0.1*factor);
    //return body;
}

