float dot2(vec2 v) { return dot(v, v); }
vec2 wrapPosition(vec2 p) { return mod(p + 1.0, 2.0) - 1.0; }
vec2 wrappedDifference(vec2 a, vec2 b) {
    vec2 diff = a - b;
    return mod(diff + 1.0, 2.0) - 1.0;
}

