// steer to avoid crowding local flockmates
const float gridSize = 3.0; // total number of boid cells along one dimension

vec2 separation(vec2 curPos, vec2 uv) {
    vec2 steer = vec2(0.0);
    int count = 0;
    float separationRadius = 0.5; // Adjust as needed to cover your simulation domain

    // Loop over every boid in the grid
    for (float j = 0.0; j < gridSize; j++) {
        for (float i = 0.0; i < gridSize; i++) {
            // Compute the UV coordinate for this neighbor boid.
            vec2 neighborUV = (vec2(i, j) + 0.5) / gridSize;

            // Skip the current boid by comparing UV coordinates
            if (distance(neighborUV, uv) < 0.001) continue;

            // Fetch the neighbor's state from the state texture
            vec4 neighborState = texture(iChannel0, neighborUV);
            vec2 neighborPos = neighborState.xy;

            // Compute the wrapped difference between current and neighbor positions.
            vec2 diff = wrappedDifference(curPos, neighborPos);
            float d = length(diff);

            // If the neighbor is within the separation radius, add a repulsion vector.
            if (d < separationRadius && d > 0.0) {
                steer += diff / d; // Weight by inverse distance.
                count++;
            }
        }
    }

    // Average the repulsion vector if any neighbors were found.
    if (count > 0)
        steer /= float(count);

    return steer;
}


vec2 alignment(vec2 uv) {
    vec2 avgVel = vec2(0.0);
    int count = 0;
    float neighborRadius = 3.5; // adjust as needed
    for (float j = 0.0; j < gridSize; j++) {
        for (float i = 0.0; i < gridSize; i++) {
            vec2 stateUV = (vec2(i, j) + 0.5) / gridSize;
            if (distance(stateUV, uv) < 0.001) continue;
            vec4 neighborState = texture(iChannel0, stateUV);
            vec2 neighborPos = neighborState.xy;
            if (distance(texture(iChannel0, uv).xy, neighborPos) < neighborRadius) {
                avgVel += neighborState.zw;
                count++;
            }
        }
    }
    if (count > 0) {
        avgVel /= float(count);
    }
    return avgVel;
}

vec2 cohesion(vec2 curPos, vec2 uv) {
    vec2 centerOfMass = vec2(0.0);
    int count = 0;
    float neighborRadius = 0.5; // adjust as needed
    for (float j = 0.0; j < gridSize; j++) {
        for (float i = 0.0; i < gridSize; i++) {
            vec2 stateUV = (vec2(i, j) + 0.5) / gridSize;
            if (distance(stateUV, uv) < 0.001) continue;
            vec4 neighborState = texture(iChannel0, stateUV);
            vec2 neighborPos = neighborState.xy;
            if (distance(curPos, neighborPos) < neighborRadius) {
                centerOfMass += neighborPos;
                count++;
            }
        }
    }
    if (count > 0) {
        centerOfMass /= float(count);
    }
    return centerOfMass - curPos;
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;  // UV in [0,1]

    // Fetch the current state for this boid
    vec4 prevState = fetchPrevState(uv);
    vec2 curPos = prevState.xy;
    vec2 curDir = prevState.zw;

    // Initialize with some randomness on frame 0
    if (iFrame == 0) {
        curPos = uv * 2.0 - 1.0; // Unique position per cell if buffer resolution matches grid
        curDir = normalize(vec2(random(uv), random(uv + 1.0)) - 0.5); // Random initial direction
    }

    // Compute the steering forces
    vec2 sep = separation(curPos, uv);
    vec2 ali = alignment(uv);
    vec2 coh = cohesion(curPos, uv);

    // Combine forces (adjust weights as needed)
    vec2 acceleration = sep * 10.15 + ali * 1.10 + coh * 10.10;

    // Update direction and normalize it
    curDir = normalize(curDir + acceleration * 0.001);

    // Update position with a chosen speed
    float speed = 0.003;
    vec2 newPos = wrapPosition(curPos + curDir * speed);

    // Write new state: position in RG, direction in BA
    fragColor = vec4(newPos, curDir);

}
